{"query": "query($owner:String!, $repo:String!) { repository(owner:$owner, name:$repo) {pr2: pullRequest(number:2) { ...history } } }
        fragment history on PullRequest {
          number
          comments(last:100) {
            totalCount
            nodes { databaseId body createdAt updatedAt lastEditedAt author { login __typename }
                    editor { login __typename } }
          }
          timelineItems(last:1, itemTypes:[CLOSED_EVENT, CONVERT_TO_DRAFT_EVENT]) {
            nodes {
              ... on ClosedEvent { createdAt }
              ... on ConvertToDraftEvent { createdAt }
            }
          }
        }", "variables": {"owner": "dashpay", "repo": "platform"}}

{"query": "query($owner:String!, $repo:String!, $number:Int!, $cursor:String) {
          repository(owner:$owner, name:$repo) {
            pullRequest(number:$number) {
              reviewThreads(first:100, after:$cursor) {
                totalCount
                pageInfo { hasNextPage endCursor }
                nodes { id isResolved
                  opening: comments(first:1) { nodes { body } }
                  comments(first:100) { nodes { author { login } createdAt } }
                }
              }
            }
          }
        }", "variables": {"owner": "dashpay", "repo": "platform", "number": 2, "cursor": null}}

{"query": "query($owner:String!, $repo:String!, $number:Int!, $cursor:String) {
      repository(owner:$owner, name:$repo) { pullRequest(number:$number) {
        commits(last:1) { nodes { commit { oid statusCheckRollup {
          contexts(first:100, after:$cursor) {
            totalCount pageInfo { hasNextPage endCursor }
            nodes {
              __typename
              ... on CheckRun { name conclusion status startedAt detailsUrl
                checkSuite { workflowRun { workflow { resourcePath } } } }
              ... on StatusContext { context state createdAt }
            } } } } } } } } }", "variables": {"owner": "dashpay", "repo": "platform", "number": 2, "cursor": null}}

